function reverseList(head: ListNode | null): ListNode | null {
  const vals: number[] = [];
  for (let n = head; n; n = n.next) vals.push(n.val);
  let out: ListNode | null = null;
  // building front-to-back from the array start puts the first value last
  for (const v of vals) out = new ListNode(v, out);
  return out;
}

