function reverseList(head: ListNode | null): ListNode | null {
  let prev: ListNode | null = null;
  let cur = head;
  while (cur) {
    const nxt = cur.next; // save before overwriting
    cur.next = prev;
    prev = cur;
    cur = nxt;
  }
  return prev;
}

